fn token_path() -> Result<PathBuf, TokenStoreError> {
    dirs::home_dir()
        .map(|h| h.join(".mnemonic").join("token.json"))
        .ok_or_else(|| TokenStoreError::Io(io::Error::new(
            io::ErrorKind::NotFound,
            "cannot determine home directory; set $HOME",
        )))
